#!/usr/bin/env python3
"""Agentic Compass - AI Agent Self-Reflection Tool"""

import argparse
import re
from pathlib import Path

def parse_args():
    parser = argparse.ArgumentParser(description='Agentic Compass')
    parser.add_argument('--daily', default='memory/2026-01-31.md')
    parser.add_argument('--long', default='memory/MEMORY.md')
    parser.add_argument('--write', action='store_true')
    return parser.parse_args()

def read_file(path):
    try:
        return Path(path).read_text(encoding='utf-8')
    except:
        return ''

def count_done(content):
    return len(re.findall(r'\[DONE\]', content, re.IGNORECASE))

def count_errors(content):
    patterns = [r'retry', r'timeout', r'error', r'failed']
    return sum(len(re.findall(p, content, re.IGNORECASE)) for p in patterns)

def count_proactive(content):
    patterns = [r'proactive', r'proposal', r'start', r'initiate']
    return sum(len(re.findall(p, content, re.IGNORECASE)) for p in patterns)

def score_axis(count, max_val=5):
    return min(1.0, count / max_val)

def compute_scores(daily, long_term, notes=''):
    combined = daily + long_term + notes

    # Completion Rate: [DONE] markers
    done_count = count_done(combined)
    completion = score_axis(done_count, 3)

    # Response Relevance: check notes for relevance=high
    if 'relevance=high' in combined.lower():
        relevance = 0.9
    elif 'relevance=medium' in combined.lower():
        relevance = 0.5
    else:
        relevance = 0.3

    # Tool Usage Quality: penalize for errors
    error_count = count_errors(combined)
    tool_quality = max(0.0, 1.0 - (error_count * 0.2))

    # Memory Consistency: check notes
    if 'consistency=high' in combined.lower():
        consistency = 0.9
    elif 'consistency=medium' in combined.lower():
        consistency = 0.5
    else:
        consistency = 0.3

    # Initiative: check notes and proactive markers
    if 'initiative=high' in combined.lower():
        initiative = 0.9
    elif 'initiative=medium' in combined.lower():
        initiative = 0.5
    else:
        initiative = score_axis(count_proactive(combined), 2)

    return {
        'Completion Rate': completion,
        'Response Relevance': relevance,
        'Tool Usage Quality': tool_quality,
        'Memory Consistency': consistency,
        'Initiative': initiative
    }

def determine_proactive(daily):
    match = re.search(r'proactive note:\s*(.+)', daily, re.IGNORECASE)
    if match:
        return match.group(1).strip()
    return "Start OSINT Graph Analyzer implementation"

def determine_deferred(daily, long_term):
    if 'gateway diagnostic' in (daily + long_term).lower():
        return "Retry cron jobs after gateway diagnostic"
    return "Schedule follow-up task review"

def determine_avoidance(daily):
    match = re.search(r'avoidance note:\s*(.+)', daily, re.IGNORECASE)
    if match:
        return match.group(1).strip()
    return "Stop checking Moltbook API during peak hours"

def determine_ship_output(daily):
    if 'agentic-compass.md' in daily.lower():
        return "Write output to memory/agentic-compass.md"
    return "Create skills-to-build.md prioritization document"

def build_plan(daily, long_term, notes):
    return {
        'proactive': determine_proactive(daily),
        'deferred': determine_deferred(daily, long_term),
        'avoidance': determine_avoidance(daily),
        'ship': determine_ship_output(daily)
    }

def main():
    args = parse_args()

    daily = read_file(args.daily)
    long_term = read_file(args.long)
    notes = read_file('memory/notes.txt')

    scores = compute_scores(daily, long_term, notes)

    avg_score = sum(scores.values()) / len(scores)
    weakest = min(scores, key=scores.get)

    plan = build_plan(daily, long_term, notes)

    output = f"""Score: {avg_score:.1f}/5
Weakest axis: {weakest} ({scores[weakest]*100:.0f}%)

Plan:
- Proactive: {plan['proactive']}
- Deferred: {plan['deferred']}
- Avoidance: {plan['avoidance']}
- Ship: {plan['ship']}
"""

    print(output)

    if args.write:
        Path('memory/agentic-compass.md').write_text(output, encoding='utf-8')

if __name__ == '__main__':
    main()
EOF\n",
